use rrrah_dedup::{anchor_rank::AnchorRankPolicy,anchor_rank_file::compare_exposure_anchor_rank_files,animated::AnimationBudget,geometry::{ProjectiveTransform,Correspondence},local_rank::LocalRankPolicy,rank_region::RankRegionPolicy};
fn main()->Result<(),Box<dyn std::error::Error>>{
 let args:Vec<_>=std::env::args().collect();let input:serde_json::Value=serde_json::from_slice(&std::fs::read(&args[1])?)?;let budget=rrrah_core::MemoryBudget::new(512*1024*1024);let mut left=rrrah_decode::DecodeRequest::new(input["left"].as_str().unwrap());let mut right=rrrah_decode::DecodeRequest::new(input["right"].as_str().unwrap());left.assume_untagged_linear_srgb=true;right.assume_untagged_linear_srgb=true;
 let decode=AnimationBudget{max_frames:1,max_pixels:12800000,max_file_bytes:5242880};let mut rows=Vec::new();
 for case in input["cases"].as_array().unwrap(){let model=ProjectiveTransform{matrix:std::array::from_fn(|i|std::array::from_fn(|j|case["transform"][i][j].as_f64().unwrap()))};let points:Vec<_>=case["witnesses"].as_array().unwrap().iter().map(|p|Correspondence{source:[p["source"][0].as_f64().unwrap(),p["source"][1].as_f64().unwrap()],target:[p["target"][0].as_f64().unwrap(),p["target"][1].as_f64().unwrap()]}).collect();let p=AnchorRankPolicy{window_radius:2,maximum_selection_checks:1176014000,local:LocalRankPolicy{rank:RankRegionPolicy{radius:2,minimum_contrast:0.005,minimum_pairs:1000,maximum_sites:80000000,maximum_pixel_reads:400000000},filter_radius:12,minimum_witnesses:20,maximum_points:28000,maximum_point_checks:392014000,minimum_point_separation:2.,target_tolerance:2.,source_tolerance:2.,minimum_coverage:0.3,minimum_agreement:0.9}};
 let e=compare_exposure_anchor_rank_files(&left,&right,model,&points,decode,p,6*decode.max_pixels,&budget,||false);rows.push(serde_json::json!({"case":case["name"],"witnesses":points.len(),"result":format!("{e:?}"),"supported":e.as_ref().is_ok_and(|e|e.anchors.supported)}));assert_eq!(budget.used(),0);
 }println!("{}",serde_json::json!({"rows":rows,"managed_used":budget.used(),"managed_peak":budget.peak()}));Ok(())
}
